import { createMemo, Show, type Component } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";

import { RandomEventsLayer, type PlotRandomEventData } from "#base/ui/lenses/layer/random-events-layer.js";

import { type PlotTooltipBaseProps } from "./helpers.js";

/** Props for the RandomEventPlotTooltipContent component */
export type RandomEventPlotTooltipContentProps = PlotTooltipBaseProps;

/**
 * Gets the random event data and resolved UI definition for the given plot coordinates.
 * Returns undefined if no valid random event data is available.
 */
export function getRandomEventInfo(
	plotCoord: float2,
): { randomEvent: PlotRandomEventData; eventData: RandomEventUIDefinition } | undefined {
	const randomEvent = RandomEventsLayer.instance.getRandomEventResult(plotCoord.x, plotCoord.y);
	if (!randomEvent) return undefined;

	let eventData: RandomEventUIDefinition | null = null;

	// Handle composite flood+volcano case
	if (randomEvent.tooltipKey === "CLASS_FLOOD_VOLCANO") {
		const floodEvent = GameInfo.RandomEventUI.lookup("CLASS_FLOOD");
		const volcanoEvent = GameInfo.RandomEventUI.lookup("CLASS_VOLCANO");
		if (floodEvent !== null && volcanoEvent !== null) {
			eventData = {
				...floodEvent,
				Tooltip: "LOC_UI_RANDOM_EVENT_FLOOD_VOLCANO_TOOLTIP",
			};
		}
	} else {
		eventData = GameInfo.RandomEventUI.lookup(randomEvent.eventClass);
	}

	if (!eventData) return undefined;

	return { randomEvent, eventData };
}

/**
 * Determines whether the random event tooltip has content to show at the given plot coordinates.
 */
export function hasRandomEventData(plotCoord: float2): boolean {
	return getRandomEventInfo(plotCoord) !== undefined;
}

/**
 * Content component for the random event plot tooltip.
 * TODO: Implement the full content rendering.
 */
export const RandomEventPlotTooltipContent: Component<RandomEventPlotTooltipContentProps> = (props) => {
	const eventInfo = createMemo(() => getRandomEventInfo(props.plotCoord));

	return (
		<Show when={eventInfo()}>
			{(info) => (
				<div class="flex flex-row text-accent-2">
					<div class="flex text-sm">
						<L10n.Stylize text={info().eventData.Tooltip} />
					</div>
				</div>
			)}
		</Show>
	);
};
